"""Auto-generated TouchDesigner Network Builder: Course 02: Real Ideas LiDAR Point Cloud + CamSchnappr & KantanMapper Rig

Loads .ply/.xyz LiDAR scans via Point File In TOP, calibrates 3D projector frustum, and outputs Kantan-style architectural masks.
Generated by Mo360 Antigravity <-> TouchDesigner Bridge (Mode B).
Run inside TouchDesigner Textport or pass via startup script.
"""

import json

PROJECT_NAME = 'course02_projection_mapping_scanner'
PARENT_PATH = '/project1'
TARGET_FPS = 60


def _resolve_op(op_type_name):
    import td
    if hasattr(td, op_type_name):
        return getattr(td, op_type_name)
    low = op_type_name.lower()
    for attr in dir(td):
        if attr.lower() == low:
            return getattr(td, attr)
    raise ValueError(f"Unknown TouchDesigner operator type: {op_type_name}")


def _set_params(node, params):
    for key, val in params.items():
        if hasattr(node.par, key):
            setattr(node.par, key, val)


def build_network(parent_path=PARENT_PATH):
    import td
    td.project.cookRate = TARGET_FPS
    root = op(parent_path)
    if root is None:
        root = op('/').create(td.baseCOMP, parent_path.strip('/'))

    comp = root.op('course02_projection_mapping_scanner')
    if comp is not None:
        comp.destroy()
    comp = root.create(td.baseCOMP, 'course02_projection_mapping_scanner')
    comp.nodeX = 0
    comp.nodeY = 0

    created = {}
    # LiDAR .ply/.xyz Loader
    _node = comp.create(_resolve_op('pointfileinTOP'), 'lidar_pointfile')
    _node.nodeX = 0
    _node.nodeY = 220
    _set_params(_node, {'file': 'scan_guildhall.ply'})
    created['lidar_pointfile'] = _node
    # Scale & Orient Point Cloud
    _node = comp.create(_resolve_op('pointtransformTOP'), 'point_transform')
    _node.nodeX = 250
    _node.nodeY = 220
    _set_params(_node, {'sx': 1.0, 'sy': 1.0, 'sz': 1.0})
    created['point_transform'] = _node
    # CamSchnappr 3D Calibration Stage
    _node = comp.create(_resolve_op('baseCOMP'), 'camschnappr_calib')
    _node.nodeX = 500
    _node.nodeY = 220
    _set_params(_node, {})
    created['camschnappr_calib'] = _node
    # KantanMapper 2D Architectural Masking
    _node = comp.create(_resolve_op('baseCOMP'), 'kantan_mapper')
    _node.nodeX = 500
    _node.nodeY = 50
    _set_params(_node, {})
    created['kantan_mapper'] = _node
    # 4K Projector Output Render
    _node = comp.create(_resolve_op('renderTOP'), 'render_projector')
    _node.nodeX = 760
    _node.nodeY = 220
    _set_params(_node, {'resolutionw': 3840, 'resolutionh': 2160})
    created['render_projector'] = _node
    # Soft-Edge Projector Blending
    _node = comp.create(_resolve_op('levelTOP'), 'edge_blend_level')
    _node.nodeX = 1010
    _node.nodeY = 220
    _set_params(_node, {'gamma1': 1.08, 'blacklevel': 0.01})
    created['edge_blend_level'] = _node
    # NDI Projector Feed
    _node = comp.create(_resolve_op('ndiOutTOP'), 'ndi_projector')
    _node.nodeX = 1250
    _node.nodeY = 220
    _set_params(_node, {'name': 'MO360_PROJECTOR_4K'})
    created['ndi_projector'] = _node

    # Wire signal flow
    created['point_transform'].inputConnectors[0].connect(created['lidar_pointfile'].outputConnectors[0])
    created['render_projector'].inputConnectors[0].connect(created['point_transform'].outputConnectors[0])
    created['edge_blend_level'].inputConnectors[0].connect(created['render_projector'].outputConnectors[0])
    created['ndi_projector'].inputConnectors[0].connect(created['edge_blend_level'].outputConnectors[0])

    print(f"[Mo360-TD] Built {len(created)} operators inside {comp.path}")
    return comp


if __name__ == "__main__":
    build_network()
